package com.djibtout.backend.controller;import com.djibtout.backend.entity.*;import com.djibtout.backend.repository.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/seller/notifications") public class SellerNotificationController{private final SellerNotificationRepository notes;private final UserRepository users;public SellerNotificationController(SellerNotificationRepository n,UserRepository u){notes=n;users=u;}private User seller(Authentication a){User u=a==null?null:users.findByEmail(a.getName()).orElse(null);return u!=null&&u.getRole()==Role.SELLER?u:null;}@GetMapping public ResponseEntity<?> list(Authentication a){User u=seller(a);return u==null?ResponseEntity.status(403).build():ResponseEntity.ok(notes.findBySellerOrderByCreatedAtDesc(u));}@PatchMapping("/{id}/read") public ResponseEntity<?> read(Authentication a,@PathVariable Long id){User u=seller(a);SellerNotification n=notes.findById(id).orElse(null);if(u==null||n==null||!n.getSeller().getId().equals(u.getId()))return ResponseEntity.status(403).build();n.setRead(true);return ResponseEntity.ok(notes.save(n));}@PatchMapping("/read-all") public ResponseEntity<?> readAll(Authentication a){User u=seller(a);if(u==null)return ResponseEntity.status(403).build();var values=notes.findBySellerOrderByCreatedAtDesc(u);values.forEach(n->n.setRead(true));notes.saveAll(values);return ResponseEntity.ok(java.util.Map.of("message","Toutes les notifications ont été marquées comme lues."));}}
